sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    /*
    This will create a CUH record in IAW Outbounds table based on the script include IAWUtils
    and IAWPayloadFormatter based on the Trade Task record subjective to Short Description from the trigger conditions
    */
	//Added as a part of MSSOTIQUBE-196
	//Reviewed as part of MSSOTIQUBE-1199
    try {
        var requestBody = {}; //JSON Obj creation for passing to the IAW Utils
        requestBody.sn_task = current.sys_id.toString();
        requestBody.request_type = "CUH";
        requestBody.payload = current.parent.u_payload.toString();

        //Invoking script include directly skipping the API response call as per Story MSSOTIQUBE- 196
        var iaw = new x_hsb11_iaw_widget.IAWUtils();
        iaw.processPayload(requestBody);
    } catch (err) {
        gs.info("Error captured from business rule - IAW Fund Code Update Handler " + err);
    }

})(current, previous);
